@import url('https://fonts.example.com/x.css');
@font-face { font-family: Brand; src: url(brand.woff2); }
.stage { font: 700 120px/1 inter; background: url(https://example.com/bg.png); }
.a { transition: opacity 0.3s; animation-play-state: paused; font-family: 'Comic Sans MS', cursive; }
.b { animation: fade 1s ease 0s paused; }
@keyframes fade { from { opacity: 0 } to { opacity: 1 } }
